INSERT INTO waf_rules VALUES(1001,'(?i)(union\s+(all\s+)?select|select\s+.*(from|where)|insert\s+into|delete\s+from|drop\s+(table|database|index)|update\s+.*set|create\s+(table|database)|alter\s+table|exec\s*\(|execute\s*\()','SQL Injection Attack Detected','attack-sqli',4,1,'2026-04-06 14:05:17','2026-04-12 18:15:06',NULL);
INSERT INTO waf_rules VALUES(1004,'(?i)(\b0x[0-9a-f]+|char\s*\(|ascii\s*\(|substring\s*\(|mid\s*\(|concat\s*\(|group_concat\s*\(|information_schema|sysobjects|syscolumns)','SQL Injection - Function and Schema Enumeration','attack-sqli',4,1,'2026-04-06 14:05:17','2026-04-06 14:05:17',NULL);
INSERT INTO waf_rules VALUES(1011,'(?i)(alert\s*\(|confirm\s*\(|prompt\s*\(|eval\s*\(|expression\s*\(|setTimeout\s*\(|setInterval\s*\()','XSS Attack - JavaScript Function Calls','attack-xss',5,1,'2026-04-06 14:05:17','2026-04-06 14:05:17',NULL);
INSERT INTO waf_rules VALUES(1012,'(?i)(<iframe|<object|<embed|<applet|<meta|<link|<style|<base)','XSS Attack - HTML Tag Injection','attack-xss',4,1,'2026-04-06 14:05:17','2026-04-06 14:05:17',NULL);
INSERT INTO waf_rules VALUES(1013,'(?i)(String\.fromCharCode|unescape\s*\(|decodeURIComponent\s*\(|atob\s*\(|\\u[0-9a-f]{4}|\\x[0-9a-f]{2})','XSS Attack - Encoding/Obfuscation','attack-xss',4,1,'2026-04-06 14:05:17','2026-04-06 14:05:17',NULL);
INSERT INTO waf_rules VALUES(1020,'(\.\.[\/\\]|\.\.[\/\\].*[\/\\]|\/etc\/passwd|\/windows\/system32|\\windows\\system32|\/proc\/self\/environ)','Path Traversal Attack - Directory Traversal','attack-lfi',5,1,'2026-04-06 14:05:17','2026-04-06 14:05:17',NULL);
INSERT INTO waf_rules VALUES(1021,'(?i)(file:\/\/|\/var\/log|\/etc\/shadow|\/etc\/hosts|boot\.ini|win\.ini|autoexec\.bat)','Local File Inclusion Attack','attack-lfi',5,1,'2026-04-06 14:05:17','2026-04-06 14:05:17',NULL);
INSERT INTO waf_rules VALUES(1022,'(?i)(php:\/\/input|php:\/\/filter|expect:\/\/|zip:\/\/|phar:\/\/|glob:\/\/)','PHP Stream Wrapper Attack','attack-lfi',5,1,'2026-04-06 14:05:17','2026-04-06 14:05:17',NULL);
INSERT INTO waf_rules VALUES(1030,'(?i)(ftp:\/\/|http:\/\/[^\s]+\.(txt|log|conf|ini|xml))','Remote File Inclusion Attack','attack-rfi',5,1,'2026-04-06 14:05:17','2026-04-06 14:05:17',NULL);
INSERT INTO waf_rules VALUES(1040,'(?i)(cmd=|exec=|system\s*\(|passthru\s*\(|shell_exec\s*\(|popen\s*\(|proc_open\s*\(|`[^`]*`)','Command Injection Attack','attack-injection',5,1,'2026-04-06 14:05:17','2026-04-06 14:05:17',NULL);
INSERT INTO waf_rules VALUES(1041,'(?i)(;\s*\w+|\|\s*\w+|&&\s*\w+|\$\(.*\)|\${.*}|\baccess\b|\bcat\b|\bchmod\b|\bcp\b|\bls\b|\bmv\b|\brm\b|\bwhoami\b|\bid\b|\buname\b)','Command Injection - System Commands','attack-injection',5,1,'2026-04-06 14:05:17','2026-04-06 14:05:17',NULL);
INSERT INTO waf_rules VALUES(1050,'(?i)(<\?php|<\?=|<%\s|%>|\${.*}|#\{.*}|@\{.*}|\$\{.*\})','Code Injection Attack','attack-injection',5,1,'2026-04-06 14:05:17','2026-04-06 14:05:17',NULL);
INSERT INTO waf_rules VALUES(1051,'(?i)(eval\s*\(|assert\s*\(|include\s*\(|require\s*\(|preg_replace.*\/e|create_function\s*\()','PHP Code Injection','attack-injection',5,1,'2026-04-06 14:05:17','2026-04-06 14:05:17',NULL);
INSERT INTO waf_rules VALUES(1060,'(?i)(xmlns:\w+\s*=|<!\[CDATA\[|<!DOCTYPE.*\[|<!ENTITY|<\!\-\-.*\-\->.*<script)','XML/XXE Injection Attack','attack-xxe',4,1,'2026-04-06 14:05:17','2026-04-06 14:05:17',NULL);
INSERT INTO waf_rules VALUES(1070,'(?i)({\s*"\$.*"|{\s*"\$where|{\s*"\$ne|{\s*"\$gt|{\s*"\$regex|{\s*"\$in|{\s*"\$nin)','NoSQL Injection Attack','attack-nosqli',4,1,'2026-04-06 14:05:17','2026-04-06 14:05:17',NULL);
INSERT INTO waf_rules VALUES(1080,'(?i)(\bldap:\/\/|\*\)|\*.*\)|\(.*\*|\(.*=.*\).*\(|cn=|ou=|dc=)','LDAP Injection Attack','attack-ldapi',4,1,'2026-04-06 14:05:17','2026-04-06 14:05:17',NULL);
INSERT INTO waf_rules VALUES(1090,'(?i)(<\w+:[^>]+>|xmlns:[^\s>]+|<soap:|<wsdl:|<\?xml)','SOAP/XML Injection','attack-soap',3,1,'2026-04-06 14:05:17','2026-04-06 14:05:17',NULL);
INSERT INTO waf_rules VALUES(1100,'(?i)(localhost|127\.0\.0\.1|0\.0\.0\.0|::1|169\.254\.|192\.168\.|10\.|172\.1[6-9]\.|172\.2[0-9]\.|172\.3[0-1]\.)','OWASP A01: SSRF - Internal IP Address Access Attempt','attack-ssrf,owasp-a01',5,1,'2026-04-06 14:05:17','2026-04-06 14:05:17',NULL);
INSERT INTO waf_rules VALUES(1101,'(?i)(file:\/\/\/|file:\/\/localhost|@127\.0\.0\.1|@localhost)','OWASP A01: SSRF - Local File/Host Access','attack-ssrf,owasp-a01',5,1,'2026-04-06 14:05:17','2026-04-06 14:05:17',NULL);
INSERT INTO waf_rules VALUES(1102,'(?i)(url=http|redirect=http|proxy=|fetch=http|load=http|src=http.*localhost)','OWASP A01: SSRF - URL Parameter Manipulation','attack-ssrf,owasp-a01',4,1,'2026-04-06 14:05:17','2026-04-06 14:05:17',NULL);
INSERT INTO waf_rules VALUES(1103,'(?i)(gopher:\/\/|dict:\/\/|ftp:\/\/.*@|ldap:\/\/|tftp:\/\/)','OWASP A01: SSRF - Dangerous Protocol Access','attack-ssrf,owasp-a01',5,1,'2026-04-06 14:05:17','2026-04-06 14:05:17',NULL);
INSERT INTO waf_rules VALUES(1110,'(?i)(\/admin|\/administrator|\/wp-admin|\/phpmyadmin|\/cpanel|\/webadmin|\/sysadmin|\/management)','OWASP A01: Force Browsing - Admin Panel Access Attempt','access-control,owasp-a01',4,1,'2026-04-06 14:05:17','2026-04-06 14:05:17',NULL);
INSERT INTO waf_rules VALUES(1111,'(?i)(\/api\/admin|\/api\/internal|\/api\/private|\/api\/system)','OWASP A01: Force Browsing - Admin API Access','access-control,owasp-a01',4,1,'2026-04-06 14:05:17','2026-04-06 14:05:17',NULL);
INSERT INTO waf_rules VALUES(1112,'(?i)(\.\.\/\.\.\/|\.\.\\\.\.\\|%2e%2e%2f|%2e%2e\/|\.\.%2f)','OWASP A01: Path Traversal - Directory Climbing','access-control,owasp-a01',5,1,'2026-04-06 14:05:17','2026-04-06 14:05:17',NULL);
INSERT INTO waf_rules VALUES(1113,'(?i)(\/etc\/passwd|\/etc\/shadow|\/windows\/system32|\/boot\.ini|\/proc\/self)','OWASP A01: Information Disclosure - System File Access','access-control,owasp-a01',5,1,'2026-04-06 14:05:17','2026-04-06 14:05:17',NULL);
INSERT INTO waf_rules VALUES(1120,'(?i)([?&])(user_?id|account_?id|profile_?id)=\d+','OWASP A01: Potential IDOR - User ID Parameter','idor,owasp-a01',3,1,'2026-04-06 14:05:17','2026-04-06 14:05:17',NULL);
INSERT INTO waf_rules VALUES(1121,'(?i)([?&])(admin|is_admin|role|user_role|access_level)=(true|1|admin|administrator)','OWASP A01: Parameter Tampering - Privilege Escalation Attempt','access-control,owasp-a01',5,1,'2026-04-06 14:05:17','2026-04-06 14:05:17',NULL);
