PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      username TEXT UNIQUE NOT NULL,
      email TEXT UNIQUE NOT NULL,
      password TEXT NOT NULL,
      role TEXT DEFAULT 'user' CHECK(role IN ('user', 'admin')),
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      last_login DATETIME,
      is_active BOOLEAN DEFAULT 1,
      is_banned BOOLEAN DEFAULT 0
    );
CREATE TABLE audit_logs (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER,
      action TEXT NOT NULL,
      ip_address TEXT,
      user_agent TEXT,
      timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
      success BOOLEAN DEFAULT 1,
      details TEXT,
      FOREIGN KEY (user_id) REFERENCES users (id)
    );
CREATE TABLE detailed_logs (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      timestamp TEXT NOT NULL,
      method TEXT NOT NULL,
      url TEXT NOT NULL,
      ip TEXT NOT NULL,
      user_agent TEXT,
      status_code INTEGER NOT NULL,
      response_time REAL,
      request_size INTEGER,
      response_size INTEGER,
      waf_checks TEXT,
      compression_info TEXT,
      ids_ips_info TEXT,
      security_events TEXT,
      headers TEXT,
      blocked BOOLEAN DEFAULT 0,
      block_reason TEXT,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE request_logs (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      timestamp TEXT NOT NULL,
      method TEXT NOT NULL,
      url TEXT NOT NULL,
      ip TEXT NOT NULL,
      user_agent TEXT,
      status_code INTEGER NOT NULL,
      response_time REAL,
      request_size INTEGER,
      response_size INTEGER,
      referer TEXT,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE user_configs (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER UNIQUE NOT NULL,
      backend_url TEXT NOT NULL,
      proxy_api_key TEXT UNIQUE NOT NULL,
      is_configured BOOLEAN DEFAULT 0,
      connectivity_status TEXT DEFAULT 'untested',
      last_test_at DATETIME,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
    );
CREATE TABLE user_request_logs (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER NOT NULL,
      timestamp TEXT NOT NULL,
      method TEXT NOT NULL,
      url TEXT NOT NULL,
      backend_url TEXT NOT NULL,
      client_ip TEXT NOT NULL,
      user_agent TEXT,
      status_code INTEGER NOT NULL,
      response_time REAL,
      request_size INTEGER,
      response_size INTEGER,
      threat_level TEXT DEFAULT 'none',
      waf_triggered BOOLEAN DEFAULT 0,
      suricata_triggered BOOLEAN DEFAULT 0,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP, compressed BOOLEAN DEFAULT 0, deduplicated BOOLEAN DEFAULT 0, compression_ratio REAL DEFAULT 0, original_size INTEGER DEFAULT 0, compressed_size INTEGER DEFAULT 0, dedup_size INTEGER DEFAULT 0, dedup_ratio REAL DEFAULT 0, app_id INTEGER REFERENCES user_applications(id) ON DELETE SET NULL,
      FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
    );
/****** CORRUPTION ERROR *******/
CREATE TABLE user_alerts (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER NOT NULL,
      alert_type TEXT NOT NULL CHECK(alert_type IN ('waf', 'suricata', 'system')),
      severity TEXT NOT NULL CHECK(severity IN ('low', 'medium', 'high', 'critical')),
      rule_id TEXT,
      rule_name TEXT,
      description TEXT NOT NULL,
      source_ip TEXT,
      target_url TEXT,
      recommended_action TEXT,
      is_read BOOLEAN DEFAULT 0,
      status TEXT DEFAULT 'open' CHECK(status IN ('open', 'acknowledged', 'resolved', 'dismissed')),
      acknowledged_by TEXT,
      acknowledged_at DATETIME,
      resolved_at DATETIME,
      comment TEXT,
      auto_blocked BOOLEAN DEFAULT 0,
      correlation_id TEXT,
      timestamp DATETIME DEFAULT CURRENT_TIMESTAMP, action TEXT DEFAULT 'detected' 
        CHECK(action IN ('detected', 'allowed', 'blocked', 'dropped', 'rejected', 'prevented')), source TEXT DEFAULT 'suricata', app_id INTEGER REFERENCES user_applications(id) ON DELETE SET NULL, scope TEXT DEFAULT 'global' CHECK(scope IN ('global','application')), occurrence_count INTEGER DEFAULT 1,
      FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
    );
/****** CORRUPTION ERROR *******/
CREATE TABLE alert_correlation (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      correlation_id TEXT UNIQUE NOT NULL,
      alert_pattern TEXT NOT NULL,
      source_ip TEXT NOT NULL,
      alert_count INTEGER DEFAULT 1,
      severity TEXT NOT NULL,
      first_seen DATETIME NOT NULL,
      last_seen DATETIME NOT NULL,
      auto_action_taken TEXT,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE automated_responses (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      correlation_id TEXT,
      action_type TEXT NOT NULL CHECK(action_type IN ('ip_block', 'rate_limit', 'notification')),
      target TEXT NOT NULL,
      reason TEXT NOT NULL,
      threshold_exceeded TEXT,
      is_active BOOLEAN DEFAULT 1,
      expires_at DATETIME,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE notification_log (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      alert_id INTEGER,
      notification_type TEXT NOT NULL CHECK(notification_type IN ('email', 'webhook', 'sms')),
      recipient TEXT NOT NULL,
      payload TEXT,
      status TEXT NOT NULL CHECK(status IN ('sent', 'failed', 'pending')),
      error_message TEXT,
      sent_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY (alert_id) REFERENCES user_alerts (id) ON DELETE CASCADE
    );
CREATE TABLE threat_intelligence (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      indicator TEXT UNIQUE NOT NULL,
      indicator_type TEXT NOT NULL CHECK(indicator_type IN ('ip', 'domain', 'url', 'hash', 'email')),
      threat_type TEXT NOT NULL,
      severity TEXT NOT NULL,
      source TEXT NOT NULL,
      confidence INTEGER DEFAULT 50,
      description TEXT,
      first_seen DATETIME NOT NULL,
      last_seen DATETIME NOT NULL,
      is_active BOOLEAN DEFAULT 1,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE alerts (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  source TEXT NOT NULL,
  severity INTEGER NOT NULL,
  category TEXT,
  signature TEXT NOT NULL,
  src_ip TEXT NOT NULL,
  dest_ip TEXT NOT NULL,
  src_port INTEGER,
  dest_port INTEGER,
  protocol TEXT,
  flow_id TEXT,
  timestamp DATETIME NOT NULL,
  description TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE waf_rules (
      id INTEGER PRIMARY KEY,
      pattern TEXT NOT NULL,
      message TEXT NOT NULL,
      tags TEXT NOT NULL,
      severity INTEGER NOT NULL DEFAULT 3,
      enabled BOOLEAN DEFAULT 1,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      created_by INTEGER,
      FOREIGN KEY (created_by) REFERENCES users (id)
    );
CREATE TABLE suricata_rules (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      sid INTEGER UNIQUE NOT NULL,
      action TEXT NOT NULL DEFAULT 'alert' CHECK(action IN ('alert', 'drop', 'reject', 'pass')),
      protocol TEXT NOT NULL DEFAULT 'http' CHECK(protocol IN ('http', 'tcp', 'udp', 'icmp', 'ip')),
      source_ip TEXT NOT NULL DEFAULT '$EXTERNAL_NET',
      source_port TEXT NOT NULL DEFAULT 'any',
      direction TEXT NOT NULL DEFAULT '->',
      dest_ip TEXT NOT NULL DEFAULT '$HTTP_SERVERS',
      dest_port TEXT NOT NULL DEFAULT 'any',
      msg TEXT NOT NULL,
      flow TEXT,
      content TEXT,
      http_uri BOOLEAN DEFAULT 0,
      http_method BOOLEAN DEFAULT 0,
      http_header BOOLEAN DEFAULT 0,
      http_request_body BOOLEAN DEFAULT 0,
      nocase BOOLEAN DEFAULT 0,
      pcre TEXT,
      classtype TEXT NOT NULL DEFAULT 'web-application-attack',
      rev INTEGER DEFAULT 1,
      priority INTEGER DEFAULT 2,
      enabled BOOLEAN DEFAULT 1,
      category TEXT DEFAULT 'custom',
      filename TEXT DEFAULT 'local.rules',
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      created_by INTEGER,
      FOREIGN KEY (created_by) REFERENCES users (id)
    );
CREATE TABLE user_applications (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER NOT NULL,
      app_name TEXT NOT NULL,
      backend_url TEXT NOT NULL,
      proxy_api_key TEXT UNIQUE NOT NULL,
      description TEXT,
      is_active BOOLEAN DEFAULT 1,
      connectivity_status TEXT DEFAULT 'untested',
      last_test_at DATETIME,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
      UNIQUE(user_id, app_name)
    );
DELETE FROM sqlite_sequence;
CREATE INDEX idx_user_logs_user_id ON user_request_logs(user_id);
CREATE INDEX idx_user_logs_timestamp ON user_request_logs(timestamp DESC);
CREATE INDEX idx_user_alerts_user_id ON user_alerts(user_id);
CREATE INDEX idx_user_alerts_timestamp ON user_alerts(timestamp DESC);
CREATE INDEX idx_user_alerts_status ON user_alerts(status);
CREATE INDEX idx_user_alerts_correlation ON user_alerts(correlation_id);
CREATE INDEX idx_alert_correlation_ip ON alert_correlation(source_ip);
CREATE INDEX idx_automated_responses_target ON automated_responses(target);
CREATE INDEX idx_threat_intelligence_indicator ON threat_intelligence(indicator);
CREATE INDEX idx_users_role ON users(role);
CREATE INDEX idx_alerts_severity ON alerts(severity);
CREATE INDEX idx_alerts_src_ip ON alerts(src_ip);
CREATE INDEX idx_alerts_timestamp ON alerts(timestamp);
COMMIT;
